class Solution {
public:
    int minimumChanges(string s, int k) {
        int n = s.size();
        vector<vector<int>> divisors(n + 1);
        for (int d = 1; d < n; d++) {
            for (int l = d * 2; l <= n; l += d) divisors[l].push_back(d);
        }
        vector<vector<int>> cost(n, vector<int>(n, 0));
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int len = j - i + 1;
                int min_c = 1e9;
                for (int d : divisors[len]) {
                    int curr = 0;
                    for (int rem = 0; rem < d; rem++) {
                        int l_idx = rem, r_idx = len - d + rem;
                        while (l_idx < r_idx) {
                            if (s[i + l_idx] != s[i + r_idx]) curr++;
                            l_idx += d;
                            r_idx -= d;
                        }
                    }
                    min_c = min(min_c, curr);
                }
                cost[i][j] = min_c;
            }
        }
        vector<vector<int>> dp(k + 1, vector<int>(n + 1, 1e9));
        dp[0][0] = 0;
        for (int cnt = 1; cnt <= k; cnt++) {
            for (int j = cnt * 2; j <= n; j++) {
                for (int i = (cnt - 1) * 2; i <= j - 2; i++) {
                    if (dp[cnt - 1][i] != 1e9) {
                        dp[cnt][j] = min(dp[cnt][j], dp[cnt - 1][i] + cost[i][j - 1]);
                    }
                }
            }
        }
        return dp[k][n];
    }
};

class Solution {
    public int minimumChanges(String s, int k) {
        int n = s.length();
        List<Integer>[] divisors = new ArrayList[n + 1];
        for (int i = 0; i <= n; i++) divisors[i] = new ArrayList<>();
        for (int d = 1; d < n; d++) {
            for (int l = d * 2; l <= n; l += d) divisors[l].add(d);
        }
        int[][] cost = new int[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int len = j - i + 1;
                int minC = 1_000_000_000;
                for (int d : divisors[len]) {
                    int curr = 0;
                    for (int rem = 0; rem < d; rem++) {
                        int lIdx = rem, rIdx = len - d + rem;
                        while (lIdx < rIdx) {
                            if (s.charAt(i + lIdx) != s.charAt(i + rIdx)) curr++;
                            lIdx += d;
                            rIdx -= d;
                        }
                    }
                    minC = Math.min(minC, curr);
                }
                cost[i][j] = minC;
            }
        }
        int[][] dp = new int[k + 1][n + 1];
        for (int[] row : dp) Arrays.fill(row, 1_000_000_000);
        dp[0][0] = 0;
        for (int cnt = 1; cnt <= k; cnt++) {
            for (int j = cnt * 2; j <= n; j++) {
                for (int i = (cnt - 1) * 2; i <= j - 2; i++) {
                    if (dp[cnt - 1][i] != 1_000_000_000) {
                        dp[cnt][j] = Math.min(dp[cnt][j], dp[cnt - 1][i] + cost[i][j - 1]);
                    }
                }
            }
        }
        return dp[k][n];
    }
}

