var minimumChanges = function(s, k) {
    const n = s.length;
    const divisors = Array.from({ length: n + 1 }, () => []);
    for (let d = 1; d < n; d++) {
        for (let l = d * 2; l <= n; l += d) divisors[l].push(d);
    }
    const cost = Array.from({ length: n }, () => new Int32Array(n));
    for (let i = 0; i < n; i++) {
        for (let j = i + 1; j < n; j++) {
            const len = j - i + 1;
            let minC = 1e9;
            for (const d of divisors[len]) {
                let curr = 0;
                for (let rem = 0; rem < d; rem++) {
                    let lIdx = rem, rIdx = len - d + rem;
                    while (lIdx < rIdx) {
                        if (s[i + lIdx] !== s[i + rIdx]) curr++;
                        lIdx += d;
                        rIdx -= d;
                    }
                }
                if (curr < minC) minC = curr;
            }
            cost[i][j] = minC;
        }
    }
    const dp = Array.from({ length: k + 1 }, () => new Int32Array(n + 1).fill(1e9));
    dp[0][0] = 0;
    for (let cnt = 1; cnt <= k; cnt++) {
        for (let j = cnt * 2; j <= n; j++) {
            for (let i = (cnt - 1) * 2; i <= j - 2; i++) {
                if (dp[cnt - 1][i] !== 1e9) {
                    const c = dp[cnt - 1][i] + cost[i][j - 1];
                    if (c < dp[cnt][j]) dp[cnt][j] = c;
                }
            }
        }
    }
    return dp[k][n];
};
